package cloud.treenewbee.quizforge.hub.ai;

import java.net.*;
import java.sql.*;
import java.time.Clock;
import java.util.*;
import org.springframework.stereotype.Service;
import cloud.treenewbee.quizforge.hub.account.*;
import cloud.treenewbee.quizforge.hub.admin.AdminAccess;
import cloud.treenewbee.quizforge.hub.storage.HubDatabase;
import static cloud.treenewbee.quizforge.hub.storage.HubDatabase.*;

@Service
public class AiUpstreams {
    private final HubDatabase db;private final AiCrypto crypto;private final AuthSettings settings;private final AiTransport transport;private final Clock clock;
    private static final Set<String> ARREARS=Set.of("Arrearage","insufficient_quota","quota_exceeded","billing_hard_limit_reached","account_deactivated","AllocationQuota.FreeTierOnly","BudgetLimitExceeded","PrepaidBillOverdue","PostpaidBillOverdue","CommodityNotPurchased");
    public static final class Candidate {
        public final String id,baseUrl,model;final String key;public final long inputPrice,outputPrice;
        Candidate(Map<String,Object> row,String key){id=row.get("id").toString();baseUrl=row.get("base_url").toString();model=row.get("model").toString();inputPrice=number(row.get("input_price"));outputPrice=number(row.get("output_price"));this.key=key;}
    }
    public record Failure(String status,String reason){}
    public AiUpstreams(HubDatabase db,AiCrypto crypto,AuthSettings settings,AiTransport transport,Clock clock){this.db=db;this.crypto=crypto;this.settings=settings;this.transport=transport;this.clock=clock;
        db.transaction(c->{var old=row(c,"SELECT * FROM official_ai_config WHERE id=1");if(old!=null&&old.get("key_cipher")!=null&&row(c,"SELECT 1 FROM ai_upstreams LIMIT 1")==null){long now=clock.millis(),price=old.get("price_per_million") instanceof Number n?n.longValue():number(defaults().get("inputPrice"));update(c,"INSERT INTO ai_upstreams(id,seq,position,note,base_url,model,key_cipher,key_hint,input_price,output_price,enabled,status,created,updated) VALUES(?,1,1,?,?,?,?,?,?,?,1,'ok',?,?)",UUID.randomUUID().toString(),"原有 Key",defaults().get("baseUrl"),old.get("model"),old.get("key_cipher"),Objects.requireNonNullElse(old.get("key_hint"),"已设置"),price,price,now,now);update(c,"UPDATE official_ai_config SET key_cipher=NULL,key_hint=NULL WHERE id=1");}return null;});
    }
    private DeviceException bad(String message){return new DeviceException(400,"AI_SETTINGS_INVALID",message);}
    public static String url(String raw){try{URI uri=URI.create(raw);if(raw.length()>300||!"https".equalsIgnoreCase(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||uri.getRawQuery()!=null||uri.getRawFragment()!=null)return null;return uri.toASCIIString().replaceAll("/+$","");}catch(Exception error){return null;}}
    private long amount(Object value,long max,boolean nullable){if(nullable&&value==null)return -1;return AdminAccess.integer(value,0,max,"金额设置无效");}
    private Object nullableAmount(Object value,long max){return amount(value,max,true)<0?null:value;}
    public Map<String,Object> defaults(){return Map.of("baseUrl",settings.value("OFFICIAL_AI_BASE_URL","https://dashscope.aliyuncs.com/compatible-mode/v1").replaceAll("/+$",""),"model",settings.value("OFFICIAL_AI_MODEL","qwen-vl-plus"),"inputPrice",priceDefault("OFFICIAL_AI_INPUT_PRICE",3),"outputPrice",priceDefault("OFFICIAL_AI_OUTPUT_PRICE",9));}
    private long priceDefault(String name,double fallback){try{double value=Double.parseDouble(settings.value(name,String.valueOf(fallback)));if(!Double.isFinite(value)||value<0||value>1000)throw new NumberFormatException();return Math.round(value*10000);}catch(NumberFormatException error){throw new IllegalArgumentException("Invalid AI price default");}}
    public boolean enabled(){return db.read(c->row(c,"SELECT 1 FROM official_ai_config WHERE id=1 AND enabled=1")!=null);}
    private boolean usable(Map<String,Object> row){return number(row.get("enabled"))!=0&&(row.get("expires")==null||number(row.get("expires"))>clock.millis())&&(row.get("remaining")==null||number(row.get("remaining"))>0);}
    private Map<String,Object> entry(Connection c,String id)throws SQLException{var row=row(c,"SELECT * FROM ai_upstreams WHERE id=?",id);if(row==null)throw new DeviceException(404,"AI_KEY_NOT_FOUND","API Key 不存在");return row;}
    private String state(Map<String,Object> row){return number(row.get("enabled"))==0?"disabled":row.get("expires")!=null&&number(row.get("expires"))<=clock.millis()?"expired":row.get("remaining")!=null&&number(row.get("remaining"))<=0||row.get("status").equals("insufficient")?"insufficient":row.get("status").equals("fault")?"fault":"ok";}
    private Map<String,Object> dto(Map<String,Object> row){var value=new LinkedHashMap<String,Object>();for(String field:List.of("id","seq","note","model","remaining","expires","calls","spent","created"))value.put(field,row.get(field));value.put("host",URI.create(row.get("base_url").toString()).getAuthority());value.put("keyHint",row.get("key_hint"));value.put("inputPrice",row.get("input_price"));value.put("outputPrice",row.get("output_price"));value.put("enabled",number(row.get("enabled"))!=0);value.put("state",state(row));value.put("reason",row.get("remaining")!=null&&number(row.get("remaining"))<=0&&!row.get("status").equals("insufficient")?"剩余金额已用完":row.get("reason"));value.put("statusAt",row.get("status_at"));value.put("readable",crypto.decrypt(row.get("key_cipher").toString(),AiCrypto.KEY_AAD)!=null);return value;}
    public List<Candidate> candidates(){return db.read(c->{var list=new ArrayList<Candidate>();for(var row:rows(c,"SELECT * FROM ai_upstreams ORDER BY position,seq")){if(!usable(row)||number(row.get("cooldown_until"))>clock.millis())continue;String key=crypto.decrypt(row.get("key_cipher").toString(),AiCrypto.KEY_AAD);if(key!=null)list.add(new Candidate(row,key));}return list;});}
    public Map<String,Object> usage(Object user){boolean available=db.read(c->rows(c,"SELECT * FROM ai_upstreams").stream().anyMatch(row->usable(row)&&crypto.decrypt(row.get("key_cipher").toString(),AiCrypto.KEY_AAD)!=null));return Map.of("enabled",enabled()&&available,"model","QuizForge 官方模型","vision",true,"balance",db.read(c->AiPoints.balance(c,user)));}
    public Object adminStatus(){return db.read(c->{var stats=row(c,"SELECT COALESCE(SUM(calls),0) totalCalls,COALESCE(SUM(points),0) totalCost FROM official_ai_usage");stats.put("todayCost",row(c,"SELECT COALESCE(SUM(points),0) n FROM official_ai_usage WHERE day=?",LocalDay.today(clock)).get("n"));stats.put("userBalance",row(c,"SELECT COALESCE(SUM(balance),0) n FROM ai_points").get("n"));return Map.of("enabled",enabled(),"keys",rows(c,"SELECT * FROM ai_upstreams ORDER BY position,seq").stream().map(this::dto).toList(),"encryptionReady",crypto.ready(),"maxKeys",20,"defaults",defaults(),"stats",stats);});}
    public Object switchService(Map<String,Object> input,Object actor){if(input.size()!=1||!(input.get("enabled") instanceof Boolean enabled))throw bad("只能切换 AI 服务开关");db.transaction(c->{AdminAccess.current(c,actor);var old=row(c,"SELECT updated FROM official_ai_config WHERE id=1");long now=Math.max(clock.millis(),old==null?0:number(old.get("updated"))+1);update(c,"INSERT INTO official_ai_config(id,enabled,model,daily_limit,monthly_tokens,updated,updated_by) VALUES(1,?,?,0,0,?,?) ON CONFLICT(id) DO UPDATE SET enabled=excluded.enabled,updated=excluded.updated,updated_by=excluded.updated_by",enabled?1:0,defaults().get("model"),now,actor);AdminAccess.audit(c,actor,enabled?"ai-service-on":"ai-service-off","ai-service",Map.of());return null;});return adminStatus();}
    public static Failure failure(int status,Map<String,Object> body){Object raw=body.get("error");String code=raw instanceof Map<?,?> error?String.valueOf(error.getOrDefault("code",null)):String.valueOf(body.getOrDefault("code",""));if(code.length()>100||!code.matches("[A-Za-z0-9_.-]*"))code="";
        if(status==429)return new Failure("throttled","被限流（HTTP 429）");if(status==402||ARREARS.contains(code))return new Failure("insufficient","欠费或额度不足");if(status==400&&!code.startsWith("InvalidApiKey"))return new Failure("rejected","请求被拒绝（HTTP 400）");return new Failure("fault",status==401?"Key 无效":status==403?"没有权限":status==404?"地址或模型不存在":"服务连接失败");}
    public void failed(String id,Failure failure){if(Set.of("throttled","rejected").contains(failure.status()))return;db.transaction(c->{update(c,"UPDATE ai_upstreams SET status=?,reason=?,status_at=?,cooldown_until=? WHERE id=?",failure.status(),failure.reason(),clock.millis(),clock.millis()+(failure.status().equals("insufficient")?600000:60000),id);return null;});}
    private Map<String,Object> probe(String base,String model,String key){long start=clock.millis();try{var result=transport.call(base,key,Map.of("model",model,"messages",List.of(Map.of("role","user","content","请只回复 OK")),"max_tokens",5),20);if(result.status()>=200&&result.status()<300&&result.body().get("choices") instanceof List<?>)return Map.of("ok",true,"ms",Math.max(0,clock.millis()-start),"status","ok","reason","测试通过");var failure=failure(result.status(),result.body());return Map.of("ok",false,"ms",Math.max(0,clock.millis()-start),"status",failure.status().equals("throttled")?"ok":failure.status().equals("rejected")?"fault":failure.status(),"reason",failure.reason());}catch(RuntimeException error){return Map.of("ok",false,"ms",Math.max(0,clock.millis()-start),"status","fault","reason","连不上或超时");}}
    public Object add(Map<String,Object> input,Object actor){var allowed=Set.of("note","baseUrl","model","apiKey","inputPrice","outputPrice","remaining","expires");if(input.keySet().stream().anyMatch(k->!allowed.contains(k)))throw bad("设置字段无效");String note=input.get("note") instanceof String s?s.strip():"",base=input.get("baseUrl") instanceof String s?url(s.strip()):null,model=input.get("model") instanceof String s?s.strip():"",key=input.get("apiKey") instanceof String s?s:"";
        if(note.codePointCount(0,note.length())>60||base==null||!model.matches("[A-Za-z0-9._:/-]{1,64}")||!key.matches("[\\x21-\\x7e]{10,200}"))throw bad("备注、HTTPS服务地址、模型或 API Key 格式不正确");long inputPrice=amount(input.get("inputPrice"),10000000,false),outputPrice=amount(input.get("outputPrice"),10000000,false);Object remaining=nullableAmount(input.get("remaining"),10000000000L),expires=input.get("expires");if(expires!=null)AdminAccess.integer(expires,clock.millis()+1,9007199254740991L,"到期时间需晚于现在");if(!crypto.ready())throw new DeviceException(409,"AI_ENCRYPTION_UNAVAILABLE","服务器尚未配置加密主密钥，不能保存 API Key");if(db.read(c->number(row(c,"SELECT COUNT(*) n FROM ai_upstreams").get("n")))>=20)throw new DeviceException(409,"AI_KEYS_FULL","最多保存 20 个 API Key");
        var test=probe(base,model,key);return db.transaction(c->{AdminAccess.current(c,actor);if(number(row(c,"SELECT COUNT(*) n FROM ai_upstreams").get("n"))>=20)throw new DeviceException(409,"AI_KEYS_FULL","最多保存 20 个 API Key");String id=UUID.randomUUID().toString();long now=clock.millis(),seq=number(row(c,"SELECT COALESCE(MAX(seq),0)+1 n FROM ai_upstreams").get("n")),position=number(row(c,"SELECT COALESCE(MAX(position),0)+1 n FROM ai_upstreams").get("n"));update(c,"INSERT INTO ai_upstreams(id,seq,position,note,base_url,model,key_cipher,key_hint,input_price,output_price,remaining,expires,enabled,status,reason,status_at,cooldown_until,created,updated) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,1,?,?,?,?,?,?)",id,seq,position,note,base,model,crypto.encrypt(key,AiCrypto.KEY_AAD),key.substring(0,3)+"…"+key.substring(key.length()-4),inputPrice,outputPrice,remaining,expires,test.get("status"),test.get("reason"),now,Boolean.TRUE.equals(test.get("ok"))?0:now+60000,now,now);AdminAccess.audit(c,actor,"ai-key-added",id,Map.of("seq",seq,"host",URI.create(base).getAuthority(),"model",model,"test",test.get("status")));return Map.of("test",test,"item",dto(entry(c,id)));});
    }
    public Object updateKey(String id,Map<String,Object> input,Object actor){if(input.keySet().stream().anyMatch(k->!Set.of("inputPrice","outputPrice","remaining").contains(k)))throw bad("只能修改输入单价、输出单价和剩余金额");return db.transaction(c->{AdminAccess.current(c,actor);var saved=entry(c,id);long ip=input.containsKey("inputPrice")?amount(input.get("inputPrice"),10000000,false):number(saved.get("input_price")),op=input.containsKey("outputPrice")?amount(input.get("outputPrice"),10000000,false):number(saved.get("output_price"));Object remaining=input.containsKey("remaining")?nullableAmount(input.get("remaining"),10000000000L):saved.get("remaining");boolean topped=input.containsKey("remaining")&&!Objects.equals(remaining,saved.get("remaining"));update(c,"UPDATE ai_upstreams SET input_price=?,output_price=?,remaining=?,updated=?"+(topped?",cooldown_until=0,status=CASE WHEN status='insufficient' THEN 'ok' ELSE status END,reason=CASE WHEN status='insufficient' THEN NULL ELSE reason END":"")+" WHERE id=?",ip,op,remaining,clock.millis(),id);AdminAccess.audit(c,actor,"ai-key-updated",id,Map.of("changed",input.keySet()));return Map.of("item",dto(entry(c,id)));});}
    public Object enabledKey(String id,Map<String,Object> input,Object actor){if(input.size()!=1||!(input.get("enabled") instanceof Boolean enabled))throw bad("请明确选择启用或停用");return db.transaction(c->{AdminAccess.current(c,actor);entry(c,id);update(c,"UPDATE ai_upstreams SET enabled=?,updated=?"+(enabled?",cooldown_until=0":"")+" WHERE id=?",enabled?1:0,clock.millis(),id);AdminAccess.audit(c,actor,enabled?"ai-key-enabled":"ai-key-disabled",id,Map.of());return Map.of("item",dto(entry(c,id)));});}
    public Object remove(String id,Object actor){return db.transaction(c->{AdminAccess.current(c,actor);var saved=entry(c,id);update(c,"DELETE FROM ai_upstreams WHERE id=?",id);AdminAccess.audit(c,actor,"ai-key-deleted",id,Map.of("seq",saved.get("seq"),"host",URI.create(saved.get("base_url").toString()).getAuthority(),"model",saved.get("model")));return Map.of("ok",true);});}
    public Object reorder(Map<String,Object> input,Object actor){if(!(input.get("ids") instanceof List<?> ids))throw bad("顺序无效");return db.transaction(c->{AdminAccess.current(c,actor);var current=rows(c,"SELECT id FROM ai_upstreams").stream().map(r->r.get("id")).toList();if(ids.size()!=current.size()||new HashSet<>(ids).size()!=ids.size()||!new HashSet<>(ids).equals(new HashSet<>(current)))throw bad("顺序无效，请刷新后重试");for(int i=0;i<ids.size();i++)update(c,"UPDATE ai_upstreams SET position=? WHERE id=?",i+1,ids.get(i));AdminAccess.audit(c,actor,"ai-keys-reordered","ai-keys",Map.of());return Map.of("ok",true);});}
    public Object test(String id,Object actor){var saved=db.read(c->entry(c,id));String key=crypto.decrypt(saved.get("key_cipher").toString(),AiCrypto.KEY_AAD);if(key==null)throw new DeviceException(409,"AI_ENCRYPTION_UNAVAILABLE","服务器缺少加密主密钥，无法读取这个 Key");var test=probe(saved.get("base_url").toString(),saved.get("model").toString(),key);return db.transaction(c->{AdminAccess.current(c,actor);entry(c,id);update(c,"UPDATE ai_upstreams SET status=?,reason=?,status_at=?,cooldown_until=? WHERE id=?",test.get("status"),test.get("reason"),clock.millis(),Boolean.TRUE.equals(test.get("ok"))?0:clock.millis()+60000,id);AdminAccess.audit(c,actor,"ai-key-tested",id,Map.of("status",test.get("status")));return Map.of("test",test,"item",dto(entry(c,id)));});}
    public static long count(Object value){return value instanceof Number n&&n.doubleValue()==n.longValue()&&n.longValue()>0&&n.longValue()<=9007199254740991L?n.longValue():0;}
    public static long cost(Map<?,?> usage,long inputPrice,long outputPrice){long in=count(usage.get("prompt_tokens")),out=count(usage.get("completion_tokens")),total=count(usage.get("total_tokens"));if(total==0)total=in+out;java.math.BigInteger amount=in>0||out>0?java.math.BigInteger.valueOf(in).multiply(java.math.BigInteger.valueOf(inputPrice)).add(java.math.BigInteger.valueOf(out).multiply(java.math.BigInteger.valueOf(outputPrice))):java.math.BigInteger.valueOf(total).multiply(java.math.BigInteger.valueOf(Math.max(inputPrice,outputPrice)));return Math.max(1,amount.add(java.math.BigInteger.valueOf(999999)).divide(java.math.BigInteger.valueOf(1000000)).min(java.math.BigInteger.valueOf(10000000000L)).longValue());}
    static class LocalDay{static String today(Clock clock){return java.time.LocalDate.now(clock.withZone(java.time.ZoneId.of("Asia/Shanghai"))).toString();}}
}
